import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:ital,wght@0,400;0,700;0,800;0,900;1,400;1,700;1,800;1,900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SplitScreenComparisonProps = Record<string, any>;

const renderHighlightedTitle = (text: string, highlight: string, color: string) => {
  if (!highlight) return text;
  const parts = text.split(new RegExp(`(${highlight})`, 'gi'));
  return parts.map((part, i) => 
    part.toLowerCase() === highlight.toLowerCase() ? 
    <span key={i} style={{ color, fontStyle: 'italic' }}>{part}</span> : 
    <span key={i} style={{ fontStyle: 'normal' }}>{part}</span>
  );
};

const SplitScreenComparison: React.FC<SplitScreenComparisonProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 8,
  leftBgColor = "#F5F5F5",
  rightBgColor = "#0B0133",
  leftTitle = "HIRING A\nMETA ADS\nCONSULTANT",
  rightTitle = "BOOKING A\nMETA ADS\nEXPERT\nON INTRO",
  rightHighlight = "ON INTRO",
  highlightColor = "#F0A6E4",
  leftPills = ["3-6 MONTHS", "EXPENSIVE", "HIT OR MISS", "BLACK BOX", "MIXED BAG"],
  rightList = ["1-HOUR", "LOW-COST", "CONSISTENT", "HIGHLY RATED", "WORLD-CLASS"],
}) => {
  useFontLoader(["Montserrat"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Proportionally increased sizes for better canvas filling
  const s = Math.min(width, height);
  const titleSize = s * 0.058;
  const pillFontSize = s * 0.034;
  const listFontSize = s * 0.034;
  const iconSize = s * 0.045;
  const rowHeight = s * 0.1;

  const actualLeftBg = transparentBackground ? "transparent" : leftBgColor;
  const actualRightBg = transparentBackground ? "transparent" : rightBgColor;
  const noiseOpacity = transparentBackground ? 0 : 0.08;
  const mainBg = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: mainBg, fontFamily: "Montserrat" }}>
      <div style={{ display: "flex", width: "100%", height: "100%", flexDirection: "row" }}>
        
        {/* LEFT PANEL */}
        <div style={{ 
          flex: 1, 
          backgroundColor: actualLeftBg, 
          display: "flex", 
          flexDirection: "column", 
          justifyContent: "center", 
          alignItems: "center", 
          position: "relative", 
          overflow: "hidden", 
          padding: s * 0.06, 
          boxSizing: "border-box" 
        }}>
          
          {/* Left Title */}
          <div style={{ marginBottom: s * 0.08, display: "flex", justifyContent: "center", alignItems: "center", width: "100%" }}>
            <div style={{ fontSize: titleSize, fontWeight: 900, fontStyle: "italic", color: "#666666", textAlign: "center", lineHeight: 1.2, letterSpacing: "-0.02em", whiteSpace: "pre-wrap" }}>
              {leftTitle}
            </div>
          </div>
          
          {/* Left Pills Stack */}
          <div style={{ position: "relative", width: "95%", height: leftPills.length * rowHeight }}>
            {leftPills.map((pill, i) => {
              const order = leftPills.length - 1 - i;
              const dropStartFrame = 15 + order * 25;
              const progress = spring({
                frame: frame - dropStartFrame,
                fps,
                config: { damping: 14, stiffness: 120, mass: 1 }
              });

              const targetY = i * rowHeight;
              const startY = -height;

              let sway = 0;
              let squish = 0;

              // Calculate impact from pills dropping later (higher order)
              for (let j = 0; j < leftPills.length; j++) {
                const orderJ = leftPills.length - 1 - j;
                if (orderJ > order) {
                  const impactFrame = 15 + orderJ * 25 + 10;
                  const t = Math.max(0, (frame - impactFrame) / fps);
                  if (t > 0 && t < 1.5) {
                    const amplitude = 1 + (leftPills.length - i) * 0.4;
                    sway += Math.exp(-t * 6) * Math.sin(t * 20) * amplitude;
                    squish += (t * 120 * Math.exp(-t * 15)) * amplitude;
                  }
                }
              }

              const currentY = interpolate(progress, [0, 1], [startY, targetY]) + squish;
              const baseRotation = (i % 2 === 0 ? -1 : 1) * (1.5 + (i % 3));
              const currentRotation = interpolate(progress, [0, 1], [i % 2 === 0 ? 15 : -15, baseRotation]) + sway;

              return (
                <div key={i} style={{
                  position: "absolute",
                  top: 0,
                  left: "50%",
                  transformOrigin: "bottom center",
                  transform: `translate(-50%, ${currentY}px) rotate(${currentRotation}deg)`,
                  backgroundColor: "#7A7A7A",
                  color: "#FFFFFF",
                  padding: `${s * 0.015}px ${s * 0.04}px`,
                  borderRadius: s * 0.05,
                  fontSize: pillFontSize,
                  fontWeight: 800,
                  fontStyle: "normal",
                  boxShadow: "0 8px 16px rgba(0,0,0,0.15)",
                  whiteSpace: "nowrap",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}>
                  {pill}
                </div>
              );
            })}
          </div>
        </div>

        {/* RIGHT PANEL */}
        <div style={{ 
          flex: 1, 
          backgroundColor: actualRightBg, 
          display: "flex", 
          flexDirection: "column", 
          justifyContent: "center", 
          alignItems: "center", 
          position: "relative", 
          overflow: "hidden", 
          padding: s * 0.06, 
          boxSizing: "border-box" 
        }}>
          
          {/* Grain Texture */}
          <div style={{ position: "absolute", inset: 0, opacity: noiseOpacity, pointerEvents: "none" }}>
            <svg width="100%" height="100%" preserveAspectRatio="none">
              <filter id="noiseFilter">
                <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="3" stitchTiles="stitch" />
              </filter>
              <rect width="100%" height="100%" filter="url(#noiseFilter)" />
            </svg>
          </div>

          {/* Right Title */}
          <div style={{ marginBottom: s * 0.08, display: "flex", justifyContent: "center", alignItems: "center", width: "100%", zIndex: 1 }}>
            <div style={{ fontSize: titleSize, fontWeight: 900, color: "#FFFFFF", textAlign: "center", lineHeight: 1.2, letterSpacing: "-0.02em", whiteSpace: "pre-wrap" }}>
              {renderHighlightedTitle(rightTitle, rightHighlight, highlightColor)}
            </div>
          </div>

          {/* Right Checkmarks List */}
          <div style={{ position: "relative", width: "85%", height: rightList.length * rowHeight, zIndex: 1 }}>
            {rightList.map((item, i) => {
              // Synchronize sequence order matching the left side's bottom-up build
              const syncOrder = rightList.length - 1 - i;
              const appearFrame = 15 + syncOrder * 25;
              const slideProg = spring({
                frame: frame - appearFrame,
                fps,
                config: { damping: 15, stiffness: 100 }
              });

              const opacity = interpolate(slideProg, [0, 1], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
              const translateX = interpolate(slideProg, [0, 1], [-s * 0.05, 0]);

              return (
                <div key={i} style={{
                  position: "absolute",
                  top: i * rowHeight,
                  left: 0,
                  width: "100%",
                  height: rowHeight,
                  display: "flex",
                  alignItems: "center",
                  opacity,
                  transform: `translateX(${translateX}px)`
                }}>
                  <svg width={iconSize} height={iconSize} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" style={{ color: "#FFFFFF", marginRight: s * 0.03, flexShrink: 0 }}>
                    <polyline points="20 6 9 17 4 12"></polyline>
                  </svg>
                  <span style={{
                    color: "#EAEAEA",
                    fontSize: listFontSize,
                    fontWeight: 700,
                    fontStyle: "normal",
                    whiteSpace: "nowrap"
                  }}>
                    {item}
                  </span>
                </div>
              );
            })}
          </div>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default SplitScreenComparison;